  arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',back:'<path d="m15 18-6-6 6-6"/>', edit:'<path d="m15 5 4 4M4 20l5-.8L20 8a2.8 2.8 0 0 0-4-4L5 15z"/>',
  trash:'<path d="M4 7h16M10 11v7M14 11v7M6 7l1 14h10l1-14M9 7V4h6v3"/>',
  check:'<path d="m5 12 5 5L20 7"/>',menu:'<path d="M3 6h18M3 12h18M3 18h18"/>',
