const ic=(name,css='')=>`<svg class="${css}" viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${ICONS[name]||ICONS.spaces}</svg>`;
const app=document.getElementById('app');
initLanguage();
function changeLanguage(code){
 const forms=captureForms(app),scrollX=window.scrollX,scrollY=window.scrollY;
 setLanguage(code);render();restoreForms(app,forms);
 app.querySelectorAll('form[data-form="booking"]').forEach(replaceWithQuote);
 app.querySelectorAll('input,select,textarea').forEach(localizeValidation);
 (app.querySelector('[role="dialog"] [data-language]')||app.querySelector('[data-language]'))?.focus({preventScroll:true});
 window.scrollTo(scrollX,scrollY);
}
const adminRoutes=['dashboard','manage-spaces','bookings','calendar','inquiries','customers','blackouts','reports','settings'];
const routeTitles=()=>({'dashboard':t("Dashboard"),'manage-spaces':t("Spaces Management"),'bookings':t("Reservations"),'calendar':t("Availability Calendar"),'inquiries':t("Customer Inquiries"),'customers':t("Customers"),'blackouts':t("Unavailability & Maintenance"),'reports':t("Reports & Exports"),'settings':t("Company Settings")});
const navItems=[['dashboard','dashboard'],['manage-spaces','spaces'],['calendar','calendar'],['bookings','bookings'],['inquiries','inquiries'],['customers','customers'],['blackouts','block'],['reports','report'],['settings','settings']];
const state={admin:false,route:'home',data:null,modal:null,search:'',type:'all',status:'all',calendarDay:localDay(),publicDay:localDay(),publicEvents:[],publicLoadedDay:null,publicLoading:false,publicError:'',publicSpaceId:'all',activeInquiryDay:'',menu:false,loading:true,authError:'',activeInquirySpace:'',toast:null};
const money=n=>t('Rs.')+' '+Number(n||0).toLocaleString(locale(),{maximumFractionDigits:0});
const dateTime=x=>x?new Date(x).toLocaleString(locale(),{day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit',hour12:true}):'—';
const dateOnly=x=>x?new Date(x).toLocaleDateString(locale(),{day:'2-digit',month:'short',year:'numeric'}):'—';
const timeOnly=x=>x?new Date(x).toLocaleTimeString(locale(),{hour:'2-digit',minute:'2-digit',hour12:true}):'—';
const localInput=x=>{if(!x)return '';const d=new Date(x);return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16)};
const dtLocal=(day,hour=9)=>`${day}T${String(hour).padStart(2,'0')}:00`;
const isoLocal=val=>val?new Date(val).toISOString():null;
const relative=(days=1,hour=9)=>{const d=new Date();d.setDate(d.getDate()+days);d.setHours(hour,0,0,0);return localInput(d)};
const typeLabel=type=>({meeting:t("Meeting / Training"),auditorium:t("Auditorium"),desk:t("Co-working desks")}[type]||type);
const rateLabel=code=>labelFor(code);
const item=(group,id)=>state.data?.[group]?.find(x=>String(x.id)===String(id));
const findSpace=id=>item('spaces',id);
const btn=(label,action,id,variant='ghost')=>`<button class="btn ${variant} mini" data-action="${h(action)}" ${id!==undefined?`data-id="${h(id)}"`:''}>${label}</button>`;
const pill=(label)=>`<span class="pill ${h(String(label).toLowerCase())}">${h(labelFor(label))}</span>`;
const imageUrl=x=>{try{let u=new URL(x);return ['https:','http:'].includes(u.protocol)?h(u.toString()):''}catch{return ''}};
const spaceImage=s=>`background-image:linear-gradient(145deg,#071a3030,#071a3000),url('${imageUrl(s?.image_url||imageSet[s?.type]||imageSet.meeting)}'),radial-gradient(circle at 75% 20%,#f2d09c66 0%,transparent 42%),linear-gradient(135deg,#91a8bd,#d0d9df 50%,#71879c)`;
const rateOf=s=>s.type==='desk'?(Number(s.rate_day)>0?`${money(s.rate_day)} <small>/ ${t("day")}</small>`:`${money(s.rate_month)} <small>/ ${t("month")}</small>`):(Number(s.rate_hour)>0?`${money(s.rate_hour)} <small>/ ${t("hour")}</small>`:`${money(s.rate_day)} <small>/ ${t("day")}</small>`);
const booked=(b)=>b.status!=='cancelled';
function showToast(message,error=false){const div=document.createElement('div');div.className='toast'+(error?' error':'');div.textContent=translateError(message);let area=document.querySelector('.toast-area');if(!area){area=document.createElement('div');area.className='toast-area';document.body.append(area)}area.append(div);setTimeout(()=>div.remove(),4200)}
async function refresh(){state.data=await load(state.admin)}
async function navigate(route){
 if(adminRoutes.includes(route)&&!state.admin){route='login'}
 state.route=route;state.modal=null;state.menu=false;state.search='';state.status='all';state.type='all';history.replaceState(null,'','#'+route);render();window.scrollTo(0,0);if(route==='availability')await refreshPublicCalendar();
}
async function refreshPublicCalendar(){
 const day=state.publicDay;
 state.publicLoading=true;state.publicError='';state.publicLoadedDay=null;
 if(state.route==='availability')render();
 try{
  const records=await loadPublicSchedule(day);
  if(day===state.publicDay){state.publicEvents=records;state.publicLoadedDay=day;}
 }catch(err){if(day===state.publicDay){state.publicError=err.message;state.publicEvents=[];}}
 finally{if(day===state.publicDay){state.publicLoading=false;if(state.route==='availability')render();}}
}
function pageHeading(title,subtitle,actions=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${subtitle}</p></div><div class="actions">${actions}</div></div>`}
function empty(text=t("No records found."),emoji='☁️'){return `<div class="empty"><div class="empty-icon">${emoji}</div><strong>${text}</strong><span>${t("Try another filter or create a new record.")}</span></div>`}
function topbar(){return `<header class="topbar"><div class="actions"><button class="btn ghost mini mobile-menu" data-action="menu" aria-label="${h(t('Open navigation'))}">${ic('menu')}</button><span class="topbar-heading">${routeTitles()[state.route]||t("Space Rental")}</span></div><div class="topbar-right">${languageSelector()}<span class="today">${new Date().toLocaleDateString(locale(),{weekday:'short',day:'numeric',month:'long',year:'numeric'})}</span><button class="btn ghost mini" data-go="home">${ic('arrow')} ${t("Public website")}</button><div class="avatar">TEC</div></div></header>`}
function sidebar(){return `<aside class="sidebar ${state.menu?'open':''}"><div class="logo"><span class="logo-icon">T.</span><div><div class="logo-title">TRACE EXPERT<br>CITY</div><div class="logo-sub">${t("Space management")}</div></div></div><div class="nav-label">${t("Workspace")}</div><nav>${navItems.map(([r,i])=>`<button data-go="${r}" class="side-link ${state.route===r?'active':''}">${ic(i)} <span>${routeTitles()[r]}</span></button>`).join('')}</nav><div class="sidebar-foot"><div class="subtle">${isCloud()?t('LIVE CLOUD WORKSPACE'):t('LOCAL DEMO WORKSPACE')}</div><div class="subtle">${isCloud()?t("Shared online data"):t("Saved in this browser only")}</div><button class="btn ghost mini" data-action="logout">${ic('logout')} ${t("Sign out")}</button></div></aside>${state.menu?`<div class="mobile-overlay" data-action="menu" aria-label="${h(t('Open navigation'))}"></div>`:''}`}
function adminShell(){let fn={'dashboard':dashboard,'manage-spaces':spacesAdmin,'bookings':bookingsAdmin,'calendar':calendarAdmin,'inquiries':inquiriesAdmin,'customers':customersAdmin,'blackouts':blocksAdmin,'reports':reportsAdmin,'settings':settingsAdmin}[state.route]||dashboard;return `<div class="app-shell">${sidebar()}<div class="main-panel">${topbar()}<main class="admin-area">${fn()}</main></div></div>`}
function headerPublic(dark=true){return `<div class="${dark?'public-dark-header':''}"><header class="public-header"><button class="public-brand" data-go="home" style="background:none;border:0;cursor:pointer"><span class="logo-icon">T.</span><span>${h(state.data.settings?.company_name||'Trace Expert City')}</span></button>${languageSelector()}<nav class="public-nav"><button data-go="catalog">${t("Our Spaces")}</button><button data-go="availability">${t("Availability calendar")}</button><button class="btn ${dark?'orange':'dark'}" data-go="catalog">${t("Book an enquiry")} ${ic('arrow')}</button><button class="extra-link" data-go="${state.admin?'dashboard':'login'}">${t("Staff")}</button></nav></header></div>`}
function footerPublic(){return `<footer class="public-footer"><div class="public-footer-inner"><div><strong>${h(state.data.settings?.company_name||'Trace Expert City')}</strong><p class="small">${h(companyAbout(state.data.settings)||t("Spaces designed for what comes next."))}</p></div><div>${h(state.data.settings?.email||t("Contact information available from our team"))}${state.data.settings?.phone?' · '+h(state.data.settings.phone):''}<br><button class="btn mini ghost" data-go="${state.admin?'dashboard':'login'}" style="margin-top:12px">${t("Staff portal")}</button></div></div></footer>`}
function spaceCardPublic(s){return `<article class="public-card"><div class="space-cover" style="${spaceImage(s)}"></div><div class="space-body"><div class="eyebrow" style="font-size:.65rem">${typeLabel(s.type)}</div><h3>${h(spaceText(s))}</h3><p>${h(spaceText(s,'description')||t("A thoughtful environment for productive work."))}</p><div class="space-meta"><span>${ic('customers','icon-inline')} ${s.type==='desk'?t('{count} desks',{count:s.inventory_count}):t('Up to {count} people',{count:s.capacity})}</span><span>${ic('check','icon-inline')} ${h((spaceText(s,'amenities')||'Wi-Fi').split(',')[0])}</span></div><div class="pub-foot"><strong class="space-price">${rateOf(s)}</strong><button data-action="public-request" data-id="${h(s.id)}" class="btn mini">${t("Inquire")} ${ic('arrow')}</button></div></div></article>`}
function homePublic(){let spaces=state.data.spaces.filter(s=>s.is_active);return `<div class="public-page"><section class="hero">${headerPublic(false)}<div class="hero-content"><div class="eyebrow">${t("SPACE FOR YOUR NEXT BIG IDEA")}</div><h1>${t("Better spaces.")}<br>${t("Brighter possibilities.")}</h1><p>${t("From focused meetings and hands-on workshops to memorable events and flexible desks. Discover the right setting at Trace Expert City.")}</p><div class="hero-actions"><button data-go="catalog" class="btn orange">${t("Explore spaces")} ${ic('arrow')}</button><button data-go="availability" class="btn ghost" style="background:#ffffff22;color:white;border-color:#ffffff55">${ic('calendar')} ${t("View booked times")}</button></div></div><div class="hero-floating"><span class="floating-icon">✦</span><div><strong>${t("Work. Connect. Create.")}</strong><small>${t("Spaces that work for you")}</small></div></div></section><section class="public-section"><div class="section-intro"><div><div class="eyebrow">${t("OUR COLLECTION")}</div><h2>${t("A space for every occasion")}</h2><p>${t("Explore thoughtfully prepared venues with flexible options for individuals, teams and events.")}</p></div><button class="btn ghost" data-go="catalog">${t("View all spaces")} ${ic('arrow')}</button></div><div class="public-cards">${spaces.slice(0,3).map(spaceCardPublic).join('')||empty(t("No active spaces yet"))}</div></section><section class="feature-band"><div class="feature-inner"><div class="feature"><div class="feature-icon">◉</div><h3>${t("Spaces for every scale")}</h3><p>${t("Meeting and training rooms, a spacious auditorium, or desks for everyday work.")}</p></div><div class="feature"><div class="feature-icon">▦</div><h3>${t("Clear availability")}</h3><p>${t("See booked venues and occupied times before sending your inquiry.")}</p><button class="tiny-link" data-go="availability">${t("Open public calendar →")}</button></div><div class="feature"><div class="feature-icon">✓</div><h3>${t("Easy inquiry process")}</h3><p>${t("Tell us what you need and our staff will follow up to arrange your booking.")}</p></div></div></section>${footerPublic()}</div>`}
function catalogPublic(){let list=state.data.spaces.filter(s=>s.is_active&&(state.type==='all'||s.type===state.type));return `<div class="public-page">${headerPublic()}<section class="catalog-banner"><div class="catalog-banner-inner"><div class="eyebrow">${t("EXPLORE OUR SPACES")}</div><h1>${t("Find the perfect setting for your next occasion.")}</h1><p>${t("Every space is designed to help ideas, teams and communities thrive. Public inquiries are requests only, not confirmed reservations.")} <button class="tiny-link" data-go="availability" style="color:#ffd898">${t("See booked venues &amp; times →")}</button></p></div></section><section class="public-section" style="padding-top:38px"><div class="catalog-filter">${[['all',t("All spaces")],['meeting',t("Meeting & training")],['auditorium',t("Auditorium")],['desk',t("Co-working desks")]].map(([x,label])=>`<button class="filter-pill ${state.type===x?'selected':''}" data-action="filter-type" data-value="${x}">${label}</button>`).join('')}</div><div class="public-cards">${list.map(spaceCardPublic).join('')||empty(t("No spaces in this category"))}</div></section>${footerPublic()}</div>`}
function requestPublic(){const s=findSpace(state.activeInquirySpace)||state.data.spaces.find(s=>s.is_active);return `<div class="public-page">${headerPublic()}<section class="catalog-banner" style="padding:35px 23px"><div class="catalog-banner-inner"><div class="eyebrow">${t("LET'S CONNECT")}</div><h1 style="font-size:2.4rem;margin-top:9px">${t("Request a space")}</h1><p>${t("Share your requirements. This sends an inquiry to our team; it does not reserve the space automatically.")}</p></div></section><div class="request-layout"><div class="request-info"><div class="space-cover" style="${spaceImage(s)}"></div><div class="inside"><h2>${h(spaceText(s)||t("Your next space"))}</h2><p class="muted small">${t("Our team will verify availability and contact you before making any reservation.")}</p><div class="space-meta"><span>${ic('spaces','icon-inline')} ${t("Meeting rooms, auditorium & desks")}</span></div><div class="hintbox">${t("No public account or online payment is needed. Confirmation happens after staff follow-up.")}</div><button class="btn ghost" type="button" data-go="availability" style="margin-top:13px">${ic('calendar')} ${t("See public availability")}</button></div></div><div class="request-form"><div class="inside"><h2>${t("Tell us about your plans")}</h2><p>${t("Fields marked * are required.")}</p><form data-form="inquiry" class="form-grid"><div class="field-row"><div class="field"><label>${t("Your name *")}</label><input class="input" name="name" required maxlength="100" placeholder="${h(t("Full name"))}"></div><div class="field"><label>${t("Email address *")}</label><input class="input" name="email" type="email" required maxlength="150" placeholder="you@company.com"></div></div><div class="field"><label>${t("Phone number *")}</label><input class="input" name="phone" required maxlength="40" placeholder="+94 77 123 4567"></div><div class="field"><label>${t("Interested space *")}</label><select class="select" name="space_id" required>${state.data.spaces.filter(x=>x.is_active).map(x=>`<option ${x.id===s?.id?'selected':''} value="${h(x.id)}">${h(spaceText(x))}</option>`).join('')}</select></div><div class="field-row"><div class="field"><label>${t("Preferred start *")}</label><input class="input" name="start_at" type="datetime-local" value="${state.activeInquiryDay?dtLocal(state.activeInquiryDay,9):relative(2,9)}" required></div><div class="field"><label>${t("Preferred end *")}</label><input class="input" name="end_at" type="datetime-local" value="${state.activeInquiryDay?dtLocal(state.activeInquiryDay,17):relative(2,17)}" required></div></div><div class="field"><label>${t("Special message")}</label><textarea class="textarea" name="message" rows="4" maxlength="1000" placeholder="${h(t("Event purpose, expected guests, setup requests..."))}"></textarea></div><input style="position:absolute;left:-10000px" name="company_website" tabindex="-1" autocomplete="off"><button type="submit" class="btn fullwidth">${ic('inquiries')} ${t("Send my inquiry")}</button><div class="subtle">${isCloud()?t("Your inquiry is saved for our staff."):t("Demo mode: inquiry saves in this browser, not on a shared server.")}</div></form></div></div></div>${footerPublic()}</div>`}
function publicCalendar(){
 const day=state.publicDay,loaded=state.publicLoadedDay===day && !state.publicLoading && !state.publicError;
 const spaces=state.data.spaces.filter(x=>x.is_active);
 const visible=spaces.filter(x=>state.publicSpaceId==='all'||String(x.id)===String(state.publicSpaceId));
 const events=loaded?state.publicEvents:[];
 const iso=(hour)=>isoLocal(dtLocal(day,hour));
 const start=isoLocal(`${day}T00:00`),end=isoLocal(`${shiftDay(day,1)}T00:00`);
 const hours=Array.from({length:12},(_,i)=>i+8);
 const blocksOf=(s)=>events.filter(e=>e.space_id===s.id&&e.kind==='blocked');
 const bookingsOf=(s)=>events.filter(e=>e.space_id===s.id&&e.kind==='booking');
 const row=(space)=>{
  const bookings=bookingsOf(space),blocks=blocksOf(space);
  const slots=hours.map(hour=>{
   const rangeStart=iso(hour),rangeEnd=iso(hour+1);
   const blocked=blocks.some(e=>intersects(e.start_at,e.end_at,rangeStart,rangeEnd));
   const fake=bookings.map(e=>({...e,status:'confirmed',reference:''}));
   const available=availabilityFor(space,fake,blocks.map(e=>({...e,reason:t("Unavailable")})),rangeStart,rangeEnd,1);
   const partial=space.type==='desk'&&available.ok&&available.remaining<space.inventory_count;
   const cls=blocked?'blocked':!available.ok?'booked':partial?'partial':'free';
   const label=blocked?t("Blocked"):!available.ok?t("Booked"):partial?t('{count} left',{count:available.remaining}):t("Free");
   return `<div class="pub-hour ${cls}" title="${h(spaceText(space))} · ${hour}:00–${hour+1}:00 · ${label}"><span>${label}</span></div>`;
  }).join('');
  const allEvents=[...bookings,...blocks].sort((a,b)=>new Date(a.start_at)-new Date(b.start_at));
  const exact=allEvents.length?allEvents.map(e=>{
   const dates=dateOnly(e.start_at)===dateOnly(e.end_at);
   const when=dates?`${timeOnly(e.start_at)} – ${timeOnly(e.end_at)}`:`${dateTime(e.start_at)} → ${dateTime(e.end_at)}`;
   return `<div class="pub-booked-line"><div class="pub-booked-icon ${e.kind==='blocked'?'blocked':'booked'}">${ic(e.kind==='blocked'?'block':'clock')}</div><div><strong>${e.kind==='blocked'?t("Unavailable"):space.type==='desk'?t('{count} desk(s) reserved',{count:Number(e.units_reserved)}):t("Booked")}</strong><small>${h(when)}</small></div></div>`;
  }).join(''):`<div class="pub-empty">${t("No reservations or blocks on this date")}</div>`;
  return `<section class="pub-venue-card"><div class="pub-venue-top"><div class="pub-venue-thumb" style="${spaceImage(space)}"></div><div><div class="eyebrow">${h(typeLabel(space.type))}</div><h3>${h(spaceText(space))}</h3><small>${space.type==='desk'?t('{count} shared desks · partial availability possible',{count:space.inventory_count}):t('Capacity {count} people',{count:space.capacity})}</small></div><button data-action="public-request-on-day" data-id="${h(space.id)}" class="btn mini">${t("Send inquiry")} ${ic('arrow')}</button></div><div class="pub-venue-schedule"><div class="pub-hour-slots">${slots}</div></div><div class="pub-venue-details"><strong class="pub-venue-details-title">${t("Occupied times")} <span>${allEvents.length}</span></strong><div class="pub-booked-lines">${exact}</div></div></section>`;
 };
 return `<div class="public-page">${headerPublic()}<section class="catalog-banner pub-calendar-banner"><div class="catalog-banner-inner"><div class="eyebrow">${t("PUBLIC VENUE SCHEDULE")}</div><h1>${t("See what's booked.")}<br>${t("Plan what's next.")}</h1><p>${t("Browse the venues and exact reserved times. Customer identities and private booking information are never shown.")}</p></div></section><section class="public-section pub-calendar-section"><div class="pub-controls card"><div class="pub-controls-heading"><div><h2>${t("Availability calendar")}</h2><p>${t("Daily venue and booking overview · times shown in your device's local timezone")}</p></div><button data-action="refresh-public-calendar" class="btn soft mini">${ic('calendar')} ${t("Refresh schedule")}</button></div><div class="pub-filter-row"><button class="btn ghost mini" data-action="public-prev-day" aria-label="${h(t("Previous day"))}">${ic('back')}</button><label class="pub-date-label">${t("Select a date")} <input type="date" class="input" data-filter="public-day" value="${h(day)}"></label><button class="btn ghost mini" data-action="public-next-day" aria-label="${h(t("Next day"))}">${ic('arrow')}</button><button class="btn ghost mini" data-action="public-today">${t("Today")}</button><select class="select pub-space-select" data-filter="public-space" aria-label="${h(t("Filter by venue"))}"><option value="all">${t("All venues")}</option>${spaces.map(x=>`<option value="${h(x.id)}" ${String(state.publicSpaceId)===String(x.id)?'selected':''}>${h(spaceText(x))}</option>`).join('')}</select></div><div class="pub-week-nav">${Array.from({length:7},(_,i)=>i-3).map(diff=>{const d=shiftDay(day,diff),x=new Date(`${d}T12:00`);return `<button class="pub-day-chip ${diff===0?'selected':''}" data-action="public-select-day" data-day="${d}"><small>${x.toLocaleDateString(locale(),{weekday:'short'})}</small><strong>${x.getDate()}</strong></button>`}).join('')}</div><div class="pub-legend"><span><i class="pub-swatch free"></i>${t("Free")}</span><span><i class="pub-swatch booked"></i>${t("Booked")}</span><span><i class="pub-swatch partial"></i>${t("Some desks left")}</span><span><i class="pub-swatch blocked"></i>${t("Unavailable")}</span></div></div>${state.publicLoading?`<div class="pub-feedback">${ic('clock')} ${t("Loading availability for")} ${h(day)}...</div>`:state.publicError?`<div class="pub-feedback error" role="alert"><strong>${t("Unable to load public bookings.")}</strong><p>${h(translateError(state.publicError))}</p><button class="btn" data-action="refresh-public-calendar">${t("Try again")}</button></div>`:!loaded?`<div class="pub-feedback">${t("Select a date to load bookings.")}</div>`:`<div class="pub-calendar-results"><div class="pub-results-heading"><div><h2>${new Date(`${day}T12:00`).toLocaleDateString(locale(),{weekday:'long',day:'numeric',month:'long',year:'numeric'})}</h2><p>${visible.length} ${t("venue(s) ·")} ${events.filter(e=>e.kind==='booking'&&visible.some(s=>s.id===e.space_id)).length} ${t("reservation(s) ·")} ${events.filter(e=>e.kind==='blocked'&&visible.some(s=>s.id===e.space_id)).length} ${t("unavailable period(s)")}</p></div><div class="pub-timeline-label">${t("Hourly overview · 08:00–20:00")}</div></div>${visible.length?`<div class="pub-hour-labels">${hours.map(hh=>`<span>${String(hh).padStart(2,'0')}:00</span>`).join('')}</div>${visible.map(row).join('')}`:empty(t("No active venues found"))}</div>`}<div class="pub-privacy-note">${ic('shield')} <span>${t("Only venue names, booking times and occupied desk quantities are public. The schedule includes pending and confirmed bookings and maintenance blocks. Cancellations are excluded. Green hours are indicative; staff make the final booking confirmation. Public inquiries do not hold a timeslot. The hourly bar covers 08:00–20:00; the exact list includes events outside these hours.")}</span></div></section>${footerPublic()}</div>`;
}
function loginPage(){return `<div class="auth-wrap"><div class="auth-card">${languageSelector()}<button class="btn ghost mini" data-go="home" style="margin-bottom:27px">${ic('back')} ${t("Back to website")}</button><div class="public-brand" style="color:#203858;margin-bottom:25px"><span class="logo-icon">T.</span> TRACE EXPERT CITY</div><div class="eyebrow">${t("STAFF ACCESS")}</div><h1>${t("Welcome back.")}</h1><p>${isCloud()?t("Sign in with an authorized staff email and password."):t("Enter the local demo workspace. Records are stored on this browser only.")}</p>${isCloud()?`<form data-form="login" class="form-grid"><div class="field"><label>${t("Email")}</label><input type="email" name="email" class="input" autocomplete="username" required></div><div class="field"><label>${t("Password")}</label><input type="password" name="password" class="input" autocomplete="current-password" required></div><button class="btn fullwidth" type="submit">${ic('shield')} ${t("Secure sign in")}</button></form>`:`<button class="btn fullwidth" data-action="enter-demo" style="margin:23px 0">${t("Open demo dashboard")} ${ic('arrow')}</button><div class="hintbox">${t("No password is used in local demo mode. For secure multi-user deployment, enable Supabase and staff authentication.")}</div>`}</div></div>`}
function stat(label,value,note,iconName='dashboard'){return `<div class="stat-card"><div class="stat-label">${label}</div><div class="stat-icon">${ic(iconName)}</div><div class="stat-value">${value}</div><div class="stat-note">${note}</div></div>`}
function dashboard(){
const {spaces,bookings,inquiries}=state.data;const actives=spaces.filter(s=>s.is_active);const coming=bookings.filter(b=>b.status!=='cancelled'&&new Date(b.end_at)>=new Date()).sort((a,b)=>new Date(a.start_at)-new Date(b.start_at)).slice(0,5);const pending=inquiries.filter(i=>i.status==='new');const expected=bookings.filter(b=>b.status!=='cancelled').reduce((a,b)=>a+Number(b.amount||0),0);
return `${pageHeading(t("Good to see you. 👋"),t("Here’s what’s happening across your spaces today."),`<button class="btn" data-action="new-booking">${ic('plus')} ${t("New booking")}</button>`)}<section class="stats-grid">${stat(t("Active spaces"),actives.length,t('{count} total spaces',{count:spaces.length}),'spaces')}${stat(t("Reservations"),bookings.filter(b=>b.status!=='cancelled').length,t("Confirmed and pending"),'bookings')}${stat(t("New inquiries"),pending.length,t("Requests waiting for action"),'inquiries')}${stat(t("Booked value"),money(expected),t("All non-cancelled bookings"),'report')}</section><section class="section-grid"><div class="card"><div class="card-head"><h3>${t("Upcoming reservations")}</h3><button class="tiny-link" data-go="bookings">${t("All bookings →")}</button></div>${coming.length?coming.map(b=>`<div class="schedule-item"><div class="schedule-time">${dateOnly(b.start_at)}<br>${timeOnly(b.start_at)}</div><div><strong>${h(spaceText(findSpace(b.space_id))||t("Unknown space"))}</strong><small>${h(b.customer_name)} · ${h(b.reference)}</small></div>${pill(b.status)}</div>`).join(''):empty(t("No upcoming bookings"),'🗓️')}</div><div class="card"><div class="card-head"><h3>${t("Quick actions")}</h3></div><div class="shortcut-grid"><button class="shortcut" data-action="new-booking"><div>✚</div>${t("New booking")}</button><button class="shortcut" data-action="new-space"><div>▦</div>${t("Add space")}</button><button class="shortcut" data-go="calendar"><div>▤</div>${t("Check dates")}</button></div><div class="divider"></div><div class="card-head"><h3>${t("Recent inquiries")}</h3><button class="tiny-link" data-go="inquiries">${t("View all →")}</button></div>${inquiries.slice(0,3).map(i=>`<div class="schedule-item" style="grid-template-columns:1fr auto"><div><strong>${h(i.name)}</strong><small>${h(spaceText(findSpace(i.space_id))||t("Requested space"))} · ${dateOnly(i.created_at)}</small></div>${pill(i.status)}</div>`).join('')||empty(t("No inquiries yet"))}</div></section><section class="section-grid"><div class="card"><div class="card-head"><h3>${t("Spaces at a glance")}</h3><button class="tiny-link" data-go="manage-spaces">${t("Manage spaces →")}</button></div>${spaces.slice(0,4).map(s=>`<div class="schedule-item" style="grid-template-columns:52px 1fr auto"><div class="table-icon" style="${spaceImage(s)}"></div><div><strong>${h(spaceText(s))}</strong><small>${h(typeLabel(s.type))} · ${s.type==='desk'?t('{count} desks',{count:s.inventory_count}):t('{count} people',{count:s.capacity})}</small></div>${pill(s.is_active?'active':'archived')}</div>`).join('')}</div><div class="card"><div class="card-head"><h3>${t("How reservations work")}</h3></div><div class="hintbox">${t("✓ Staff check a space’s availability by exact start and end time.")}<br>${t("✓ Overlapping room bookings are rejected.")}<br>${t("✓ Desk bookings respect the number of desks available.")}<br>${t("✓ Public inquiries do not hold a space until staff book it.")}</div><p class="small muted" style="margin-top:13px">${isCloud()?t("Online mode is connected. Final conflict checks also run in PostgreSQL."):t("Local demo is active. All data remains on this device; connect Supabase to share it across the company.")}</p></div></section>`}
function spacesAdmin(){
 const list=state.data.spaces.filter(s=>(state.type==='all'||s.type===state.type)&&(`${s.name} ${s.amenities} ${s.description} ${spaceText(s)} ${spaceText(s,'description')} ${spaceText(s,'amenities')}`.toLowerCase().includes(state.search.toLowerCase())));
 return `${pageHeading(t("Manage your spaces"),t("Add, edit, archive or remove rooms, halls and desk inventory."),`<button class="btn" data-action="new-space">${ic('plus')} ${t("Add a space")}</button>`)}<div class="toolbar"><input class="input" name="search" data-filter="search" placeholder="${h(t("Search spaces..."))}" value="${h(state.search)}"><select class="select" data-filter="type"><option value="all">${t("All categories")}</option>${['meeting','auditorium','desk'].map(t=>`<option value="${t}" ${state.type===t?'selected':''}>${typeLabel(t)}</option>`).join('')}</select><span class="subtle">${list.length} ${t("spaces")}</span></div><div class="space-grid">${list.map(s=>`<article class="space-card"><div class="space-cover" style="${spaceImage(s)}">${pill(s.is_active?'active':'archived')}</div><div class="space-body"><div class="eyebrow" style="font-size:.67rem">${typeLabel(s.type)}</div><h3>${h(spaceText(s))}</h3><p>${h(spaceText(s,'description')||t("No description"))}</p><div class="space-meta"><span>👥 ${s.type==='desk'?t('{count} desks available',{count:s.inventory_count}):t('Capacity {count}',{count:s.capacity})}</span><span>⚙ ${h(spaceText(s,'amenities')||t("None listed"))}</span></div><div class="space-footer"><div class="space-price">${rateOf(s)}</div><div class="hscroll-actions">${btn(ic('edit'),'edit-space',s.id)}${btn(s.is_active?t("Archive"):t("Restore"),'toggle-space',s.id)}${btn(ic('trash'),'delete-space',s.id,'danger')}</div></div></div></article>`).join('')||empty(t("No matching spaces"))}</div>`}
function bookingsAdmin(){
 const list=state.data.bookings.filter(b=>(state.status==='all'||b.status===state.status)&&(`${b.reference} ${b.customer_name} ${b.customer_email} ${findSpace(b.space_id)?.name||''} ${spaceText(findSpace(b.space_id))}`.toLowerCase().includes(state.search.toLowerCase()))).sort((a,b)=>new Date(b.start_at)-new Date(a.start_at));
 return `${pageHeading(t("Reservations"),t("Manage reservation details, changes, payments and cancellations."),`<button class="btn" data-action="new-booking">${ic('plus')} ${t("New reservation")}</button>`)}<div class="toolbar"><input class="input" name="search" data-filter="search" placeholder="${h(t("Search customer, space or reference"))}" value="${h(state.search)}"><select class="select" data-filter="status"><option value="all">${t("All statuses")}</option>${['pending','confirmed','completed','cancelled'].map(x=>`<option ${state.status===x?'selected':''} value="${x}">${h(labelFor(x))}</option>`).join('')}</select><button class="btn ghost mini" data-action="export" data-id="bookings">${ic('download')} ${t("Export CSV")}</button></div><div class="card" style="padding:5px 0"><div class="table-wrap"><table class="data-table"><thead><tr><th>${t("Reference / Customer")}</th><th>${t("Space")}</th><th>${t("Dates & time")}</th><th>${t("Total / Paid")}</th><th>${t("Status")}</th><th>${t("Actions")}</th></tr></thead><tbody>${list.map(b=>`<tr><td><strong class="info-text clickable" data-action="view-booking" data-id="${h(b.id)}">${h(b.reference)}</strong><br><strong>${h(b.customer_name)}</strong><br><small>${h(b.customer_email||b.customer_phone||'')}</small></td><td><strong>${h(spaceText(findSpace(b.space_id))||t("Deleted"))}</strong><br><small>${b.units_reserved>1?t('{count} desks',{count:b.units_reserved}):h(b.purpose||'—')}</small></td><td>${dateOnly(b.start_at)}<br><small>${timeOnly(b.start_at)} – ${dateTime(b.end_at)}</small></td><td><strong>${money(b.amount)}</strong><br><small>${t("Paid")} ${money(b.amount_paid)}</small></td><td>${pill(b.status)}<br>${pill(b.payment_status)}</td><td><div class="hscroll-actions">${btn(t("View"),'view-booking',b.id)}${btn(t("Edit"),'edit-booking',b.id)}${b.status!=='cancelled'?btn(t("Cancel"),'cancel-booking',b.id,'danger'):''}</div></td></tr>`).join('')||`<tr><td colspan="6">${empty(t("No reservations match"))}</td></tr>`}</tbody></table></div></div><p class="note" style="margin-top:14px">${t("Pending, confirmed and completed bookings hold their time slots. Cancelling releases a slot; deleting a reservation is available from its details.")}</p>`}
function inquiriesAdmin(){const list=state.data.inquiries.filter(i=>(state.status==='all'||i.status===state.status)&&(`${i.name} ${i.email} ${i.phone} ${findSpace(i.space_id)?.name||''} ${spaceText(findSpace(i.space_id))}`.toLowerCase().includes(state.search.toLowerCase()))).sort((a,b)=>new Date(b.created_at)-new Date(a.created_at));return `${pageHeading(t("Customer inquiries"),t("Review visitor requests, contact customers and convert inquiries to bookings."),`<button class="btn ghost" data-action="export" data-id="inquiries">${ic('download')} ${t("Export")}</button>`)}<div class="toolbar"><input name="search" data-filter="search" class="input" placeholder="${h(t("Search inquiries"))}" value="${h(state.search)}"><select data-filter="status" class="select"><option value="all">${t("All inquiries")}</option>${['new','contacted','converted','closed'].map(x=>`<option value="${x}" ${state.status===x?'selected':''}>${h(labelFor(x))}</option>`).join('')}</select></div><div class="card" style="padding:5px 0"><div class="table-wrap"><table class="data-table"><thead><tr><th>${t("Request")}</th><th>${t("Interested space")}</th><th>${t("Preferred period")}</th><th>${t("Status")}</th><th>${t("Actions")}</th></tr></thead><tbody>${list.map(i=>`<tr><td><strong>${h(i.name)}</strong><br><small>${h(i.email)}</small><br><small>${h(i.phone)}</small></td><td><strong>${h(spaceText(findSpace(i.space_id))||t("Unknown space"))}</strong><br><small>${h((i.message||'').slice(0,60))}</small></td><td>${dateOnly(i.start_at)}<br><small>${timeOnly(i.start_at)} – ${dateTime(i.end_at)}</small></td><td>${pill(i.status)}</td><td><div class="hscroll-actions">${btn(t("Details"),'view-inquiry',i.id)}${i.status!=='converted'?btn(t("Convert"),'convert-inquiry',i.id,'soft'):''}</div></td></tr>`).join('')||`<tr><td colspan="5">${empty(t("No matching inquiries"))}</td></tr>`}</tbody></table></div></div>`}
function customersAdmin(){const list=state.data.customers.filter(x=>`${x.full_name} ${x.email} ${x.phone} ${x.company}`.toLowerCase().includes(state.search.toLowerCase()));return `${pageHeading(t("Customers"),t("Maintain a reliable directory of customer contacts."),`<button class="btn" data-action="new-customer">${ic('plus')} ${t("Add customer")}</button>`)}<div class="toolbar"><input class="input" name="search" data-filter="search" placeholder="${h(t("Search customers"))}" value="${h(state.search)}"><button class="btn ghost mini" data-action="export" data-id="customers">${ic('download')} ${t("Export CSV")}</button></div><div class="card" style="padding:5px 0"><div class="table-wrap"><table class="data-table"><thead><tr><th>${t("Customer")}</th><th>${t("Contact")}</th><th>${t("Company")}</th><th>${t("Reservations")}</th><th>${t("Actions")}</th></tr></thead><tbody>${list.map(c=>`<tr><td><strong>${h(c.full_name)}</strong></td><td>${h(c.email||'—')}<br><small>${h(c.phone||'')}</small></td><td>${h(c.company||'—')}</td><td>${state.data.bookings.filter(b=>b.customer_id===c.id).length}</td><td><div class="hscroll-actions">${btn(t("Edit"),'edit-customer',c.id)}${btn(t("Delete"),'delete-customer',c.id,'danger')}</div></td></tr>`).join('')||`<tr><td colspan="5">${empty(t("No customers found"))}</td></tr>`}</tbody></table></div></div>`}
function blocksAdmin(){const list=[...state.data.blackouts].sort((a,b)=>new Date(b.start_at)-new Date(a.start_at));return `${pageHeading(t("Blocked periods"),t("Reserve time for maintenance, private events or temporary closures."),`<button class="btn" data-action="new-block">${ic('plus')} ${t("Block time")}</button>`)}<div class="warnbox" style="margin-bottom:17px">${t("A blocked period makes an entire space unavailable. The system rejects a block that overlaps an existing active reservation.")}</div><div class="card" style="padding:5px 0"><div class="table-wrap"><table class="data-table"><thead><tr><th>${t("Space")}</th><th>${t("Start")}</th><th>${t("End")}</th><th>${t("Reason")}</th><th>${t("Actions")}</th></tr></thead><tbody>${list.map(b=>`<tr><td><strong>${h(spaceText(findSpace(b.space_id))||t("Unknown"))}</strong></td><td>${dateTime(b.start_at)}</td><td>${dateTime(b.end_at)}</td><td>${h(b.reason)}</td><td><div class="hscroll-actions">${btn(t("Edit"),'edit-block',b.id)}${btn(t("Delete"),'delete-block',b.id,'danger')}</div></td></tr>`).join('')||`<tr><td colspan="5">${empty(t("No blocked periods"))}</td></tr>`}</tbody></table></div></div>`}
function reportsAdmin(){
 const {bookings,spaces,customers,inquiries}=state.data;const active=bookings.filter(booked);const paid=active.reduce((sum,b)=>sum+Number(b.amount_paid||0),0);const bookedValue=active.reduce((sum,b)=>sum+Number(b.amount||0),0);const outstanding=Math.max(0,bookedValue-paid);const counts=spaces.map(s=>({name:spaceText(s),count:active.filter(b=>b.space_id===s.id).length,value:active.filter(b=>b.space_id===s.id).reduce((sum,b)=>sum+Number(b.amount||0),0)}));const max=Math.max(1,...counts.map(s=>s.count));
 return `${pageHeading(t("Reports & insights"),t("A live snapshot of reservations, recorded payments and space performance."),`<button class="btn" data-action="export" data-id="bookings">${ic('download')} ${t("Bookings CSV")}</button>`)}<div class="stats-grid">${stat(t("Total reservations"),bookings.length,t("All statuses"),'bookings')}${stat(t("Booked value"),money(bookedValue),t("Excludes cancelled"),'report')}${stat(t("Payments recorded"),money(paid),t("Manually marked received"),'check')}${stat(t("Outstanding"),money(outstanding),t("Not yet recorded as paid"),'clock')}</div><section class="section-grid"><div class="card"><div class="card-head"><h3>${t("Most booked spaces")}</h3></div>${counts.map(s=>`<div class="report-row"><div class="report-heading"><strong>${h(s.name)}</strong><span>${s.count} ${t("bookings ·")} ${money(s.value)}</span></div><div class="progress"><i style="width:${100*s.count/max}%"></i></div></div>`).join('')||empty(t("No spaces"))}</div><div class="card"><div class="card-head"><h3>${t("Record exports")}</h3></div><div class="form-grid"><button class="btn ghost fullwidth" data-action="export" data-id="bookings">${ic('download')} ${t("Download all reservations (CSV)")}</button><button class="btn ghost fullwidth" data-action="export" data-id="spaces">${ic('download')} ${t("Download spaces (CSV)")}</button><button class="btn ghost fullwidth" data-action="export" data-id="customers">${ic('download')} ${t("Download customers (CSV)")}</button><button class="btn ghost fullwidth" data-action="export" data-id="inquiries">${ic('download')} ${t("Download inquiries (CSV)")}</button></div><div class="divider"></div><div class="kpi-duo"><div class="mini-panel">${t("Customers")}<strong>${customers.length}</strong></div><div class="mini-panel">${t("Inquiries")}<strong>${inquiries.length}</strong></div></div><p class="note" style="margin-top:17px">${t("Reports reflect current records, not tax invoices or bank reconciliation.")}</p></div></section>`}
function settingsAdmin(){const s=state.data.settings;return `${pageHeading(t("Company settings"),t("Edit the information shown across the public and administrative workspace.")) }<div class="split"><div class="card"><h3>${t("Company information")}</h3><p class="subtle">${t("Visible on the public website and contact area.")}</p><form data-form="settings" class="form-grid"><div class="field"><label>${t("Company name")}</label><input class="input" name="company_name" value="${h(s.company_name)}" required></div><div class="field"><label>${t("Admin contact email")}</label><input class="input" name="email" type="email" value="${h(s.email)}"></div><div class="field-row"><div class="field"><label>${t("Phone")}</label><input class="input" name="phone" value="${h(s.phone)}"></div><div class="field"><label>${t("Currency")}</label><input class="input" value="LKR" disabled><small>${t("Demo uses Sri Lankan rupees.")}</small></div></div><div class="field"><label>${t("Address")}</label><input class="input" name="address" value="${h(s.address)}"></div><div class="field"><label>${t("Opening hours")}</label><input class="input" name="opening_hours" value="${h(s.opening_hours)}"></div><div class="field"><label>${t("Short description")}</label><textarea class="textarea" name="about">${h(s.about)}</textarea></div><button type="submit" class="btn">${t("Save company settings")}</button></form></div><div class="card"><h3>${t("Workspace & data")}</h3><div class="hintbox"><strong>${isCloud()?t("Supabase online mode"):t("Free offline demo mode")}</strong><br>${isCloud()?t("Connected to a shared Supabase project. Staff sign-in and database constraints protect reservation writes."):t("You can explore the complete app with no API keys. Demo information is saved in localStorage and is visible only in this browser.")}</div><div class="divider"></div><h3>${t("Important reminders")}</h3><p class="small muted">${t("Public visitors submit inquiries only. Admin users approve availability by entering reservations. Adding an email notification requires server-side email provider credentials and is optional.")}</p>${!isCloud()?`<div class="divider"></div><button class="btn danger" data-action="reset-demo">${t("Reset all demo data")}</button><p class="subtle">${t("This clears changes made to the sample records on this browser.")}</p>`:''}</div></div>`}
function calendarAdmin(){const day=state.calendarDay;const start=isoLocal(dtLocal(day,8)),end=isoLocal(dtLocal(day,20));const daySpaces=state.data.spaces.filter(s=>s.is_active);const all=state.data.bookings;const blocks=state.data.blackouts;const timeMs=12*3600000;return `${pageHeading(t("Availability calendar"),t("Review bookings and maintenance by exact time. Click a free grid cell to create a booking."),`<button class="btn" data-action="new-booking">${ic('plus')} ${t("New reservation")}</button>`)}<div class="card"><div class="calendar-toolbar"><div class="actions"><div class="field"><label>${t("Selected day")}</label><input class="input" type="date" data-filter="calendar-day" value="${day}"></div></div><div class="actions"><span class="pill confirmed">${t("Confirmed / completed")}</span><span class="pill pending">${t("Pending")}</span><span class="pill" style="background:#ffeaca">${t("Blocked")}</span></div></div><div class="availability-list">${daySpaces.map(s=>{const overlaps=all.filter(b=>b.space_id===s.id&&booked(b)&&intersects(b.start_at,b.end_at,start,end));const blackout=blocks.find(b=>b.space_id===s.id&&intersects(b.start_at,b.end_at,start,end));return `<div class="avail-card"><strong>${h(spaceText(s))}</strong><span class="subtle">${s.type==='desk'?t('{count} total desks',{count:s.inventory_count}):t('{count} seats',{count:s.capacity})} · ${overlaps.length} ${t("reservation(s)")}</span><br>${blackout?pill('blocked'):overlaps.length?pill('partly booked'):pill('available')}</div>`}).join('')}</div><div class="cal-scroll"><div class="cal-grid"><div class="cal-hours"><span>${t("Space / time")}</span>${Array.from({length:12},(_,i)=>`<span>${String(8+i).padStart(2,'0')}:00</span>`).join('')}</div>${daySpaces.map(s=>{const bookings=all.filter(b=>b.space_id===s.id&&booked(b)&&intersects(b.start_at,b.end_at,start,end));const conflicts=blocks.filter(b=>b.space_id===s.id&&intersects(b.start_at,b.end_at,start,end));const events=[...bookings.map(b=>({...b,isBlock:false})),...conflicts.map(b=>({...b,isBlock:true}))];return `<div class="cal-lane"><div class="cal-title">${h(spaceText(s))}<small>${typeLabel(s.type)}</small></div>${Array.from({length:12},(_,i)=>`<div class="cal-cell" data-action="calendar-slot" data-id="${h(s.id)}" data-hour="${8+i}"></div>`).join('')}${events.map(b=>{const left=Math.max(0,(new Date(b.start_at)-new Date(start))/timeMs),right=Math.min(1,(new Date(b.end_at)-new Date(start))/timeMs);return `<div class="cal-event ${b.isBlock?'block':b.status==='pending'?'pending':''}" style="left:calc(165px + (100% - 165px)*${left});width:calc((100% - 165px)*${right-left} - 2px)" title="${h(b.isBlock?b.reason:b.customer_name)}" data-action="${b.isBlock?'edit-block':'view-booking'}" data-id="${h(b.id)}">${b.isBlock?'🔧 '+h(b.reason):h(b.customer_name)+(s.type==='desk'?' · '+t('{count} desks',{count:b.units_reserved}):'')}</div>`}).join('')}</div>`}).join('')}</div></div><p class="note" style="margin:14px 0 0">${t("The timeline displays 08:00–20:00 for one day. Availability checks also cover bookings outside these hours and multi-day reservations. Desk events may overlap when seats remain.")}</p></div>`}
const opt=(v,selected,label)=>`<option value="${h(v)}" ${v===selected?'selected':''}>${h(label??v)}</option>`;
function field(label,name,value='',inputType='text',extra=''){return `<div class="field"><label>${label}</label><input class="input" type="${inputType}" name="${name}" value="${h(value)}" ${extra}></div>`}
function textArea(label,name,value='',extra=''){return `<div class="field"><label>${label}</label><textarea class="textarea" name="${name}" ${extra}>${h(value)}</textarea></div>`}
function selectField(label,name,choices,value,extra=''){return `<div class="field"><label>${label}</label><select class="select" name="${name}" ${extra}>${choices.map(x=>opt(x[0],value,x[1])).join('')}</select></div>`}
function modalFrame(title,content,narrow=false){return `<div class="modal-backdrop" data-action="modal-backdrop"><div class="modal ${narrow?'narrow':''}" role="dialog" aria-modal="true" aria-label="${h(title)}"><div class="modal-head"><h2>${title}</h2><div class="modal-tools">${languageSelector()}<button data-action="close-modal" class="close-x" aria-label="${h(t("Close"))}">×</button></div></div><div class="modal-body">${content}</div></div></div>`}
function modalSpace(s){const edit=!!s;const x=s||{name:'',type:'meeting',capacity:10,inventory_count:1,amenities:"Wi-Fi, AC",rate_hour:0,rate_day:0,rate_week:0,rate_month:0,description:'',conditions:'',image_url:'',is_active:true};return modalFrame(edit?t("Edit space"):t("Add a new space"),`<form class="form-grid" data-form="space" ${edit?`data-id="${h(x.id)}"`:''}><div class="field-row">${field(t("Space name *"),'name',x.name,'text','required maxlength="120"')}${selectField(t("Category *"),'type',[['meeting',t("Meeting / training room")],['auditorium',t("Auditorium")],['desk',t("Co-working desk zone")]],x.type,'required')}</div><div class="field-row">${field(t("Capacity per unit *"),'capacity',x.capacity,'number','min="1" required')}${field(t("Reservable desk units *"),'inventory_count',x.inventory_count,'number','min="1" required')} </div><div class="hintbox">${t("For rooms and the auditorium, the number of reservable units must be")} <strong>1</strong>${t(". For co-working desks, enter the number of separate desks (for example, 14).")}</div><div class="field-row">${field(t("Rate per hour (Rs.)"),'rate_hour',x.rate_hour,'number','min="0" step="0.01"')}${field(t("Rate per day (Rs.)"),'rate_day',x.rate_day,'number','min="0" step="0.01"')}</div><div class="field-row">${field(t("Rate per week (Rs.)"),'rate_week',x.rate_week,'number','min="0" step="0.01"')}${field(t("Rate per 30 days (Rs.)"),'rate_month',x.rate_month,'number','min="0" step="0.01"')}</div>${field(t("Amenities (comma separated)"),'amenities',x.amenities)}${field(t("Cover image URL (optional)"),'image_url',x.image_url,'url')}${textArea(t("Description"),'description',x.description)}${textArea(t("Rules and conditions"),'conditions',x.conditions)}<label class="checkline"><input name="is_active" type="checkbox" ${x.is_active?'checked':''}> ${t("Allow new reservations for this space")}</label><div class="form-actions"><button class="btn ghost" type="button" data-action="close-modal">${t("Cancel")}</button><button class="btn" type="submit">${edit?t("Save changes"):t("Create space")}</button></div></form>`)}
function modalCustomer(c){const x=c||{full_name:'',email:'',phone:'',company:'',notes:''};return modalFrame(c?t("Edit customer"):t("New customer"),`<form data-form="customer" ${c?`data-id="${h(c.id)}"`:''} class="form-grid">${field(t("Full name *"),'full_name',x.full_name,'text','required')}${field(t("Email"),'email',x.email,'email')}${field(t("Phone"),'phone',x.phone)}${field(t("Company / organization"),'company',x.company)}${textArea(t("Notes"),'notes',x.notes)}<div class="form-actions"><button type="button" class="btn ghost" data-action="close-modal">${t("Cancel")}</button><button class="btn" type="submit">${t("Save customer")}</button></div></form>`,true)}
function modalBlock(b){const x=b||{space_id:state.data.spaces[0]?.id||'',start_at:isoLocal(relative(1,9)),end_at:isoLocal(relative(1,17)),reason:''};return modalFrame(b?t("Edit blocked period"):t("Block a space"),`<form class="form-grid" data-form="blackout" ${b?`data-id="${h(b.id)}"`:''}>${selectField(t("Space *"),'space_id',state.data.spaces.map(s=>[s.id,spaceText(s)]),x.space_id,'required')}<div class="field-row">${field(t("Start *"),'start_at',localInput(x.start_at),'datetime-local','required')}${field(t("End *"),'end_at',localInput(x.end_at),'datetime-local','required')}</div>${field(t("Reason *"),'reason',x.reason,'text','required maxlength="200"')}<div class="warnbox">${t("Blocking time will reject new reservations across the entire chosen space. Any existing booking conflict must be resolved first.")}</div><div class="form-actions"><button type="button" class="btn ghost" data-action="close-modal">${t("Cancel")}</button><button class="btn" type="submit">${t("Save blocked period")}</button></div></form>`,true)}
function modalBooking(b,fromInquiry=null,prefill={}){
 const x=b||{id:'',customer_id:fromInquiry?.customer_id||'',customer_name:fromInquiry?.name||'',customer_email:fromInquiry?.email||'',customer_phone:fromInquiry?.phone||'',space_id:prefill.spaceId||fromInquiry?.space_id||state.data.spaces.find(s=>s.is_active)?.id||'',start_at:fromInquiry?.start_at||isoLocal(prefill.start||relative(1,9)),end_at:fromInquiry?.end_at||isoLocal(prefill.end||relative(1,10)),units_reserved:1,rate_type:'hour',status:'confirmed',payment_status:'unpaid',amount_paid:0,payment_method:'cash',purpose:'',attendees:1,special_requests:fromInquiry?.message||'',internal_notes:'',discount:0};
 const selected=findSpace(x.space_id);const quote=selected?quoteBooking(selected,x):null;const related=fromInquiry?`data-inquiry="${h(fromInquiry.id)}"`:'';
 return modalFrame(b?t("Edit reservation"):fromInquiry?t("Convert inquiry to reservation"):t("Create reservation"),`<form data-form="booking" ${b?`data-id="${h(b.id)}"`:''} ${related} class="form-grid"><div class="hintbox"><strong>${t("Live conflict prevention")}</strong> ${t("— bookings cannot overlap for a room or exceed the available desk inventory. A failed check leaves existing bookings unchanged.")}</div><div class="field-row">${selectField(t("Space *"),'space_id',state.data.spaces.filter(s=>s.is_active||s.id===x.space_id).map(s=>[s.id,spaceText(s)]),x.space_id,'required data-quote-field')}${selectField(t("Status"),'status',[['pending',t("Pending")],['confirmed',t("Confirmed")],['completed',t("Completed")],['cancelled',t("Cancelled")]],x.status)}</div><div class="field-row">${field(t("Start date and time *"),'start_at',localInput(x.start_at),'datetime-local','required data-quote-field')}${field(t("End date and time *"),'end_at',localInput(x.end_at),'datetime-local','required data-quote-field')}</div><div class="field-row">${selectField(t("Billing unit"),'rate_type',[['hour',t("Per hour")],['day',t("Per day")],['week',t("Per week")],['month',t("Per 30-day period")]],x.rate_type,'data-quote-field')}${field(t("Units / desks"),'units_reserved',x.units_reserved,'number','required min="1" data-quote-field')}</div><div class="quote-preview hintbox">${quote?h(t('Quote: {total} ({periods} {unit} block(s), {count} unit(s))',{total:money(quote.total),periods:quote.periodUnits,unit:rateLabel(x.rate_type),count:x.units_reserved})):t("Choose a space and dates.")}</div><div class="divider"></div><h3 style="margin:0">${t("Customer & event")}</h3><div class="field"> <label>${t("Choose a customer (optional)")}</label><select class="select" name="customer_id" data-customer-change><option value="">${t("Enter customer details below")}</option>${state.data.customers.map(c=>opt(c.id,x.customer_id,c.full_name+(c.company?' — '+c.company:''))).join('')}</select></div><div class="field-row">${field(t("Customer / contact name *"),'customer_name',x.customer_name,'text','required maxlength="120"')}${field(t("Email"),'customer_email',x.customer_email,'email')}</div><div class="field-row">${field(t("Phone"),'customer_phone',x.customer_phone)}${field(t("Expected attendees"),'attendees',x.attendees,'number','min="1"')}</div>${field(t("Reservation purpose"),'purpose',x.purpose)}${textArea(t("Special requirements"),'special_requests',x.special_requests)}<div class="divider"></div><h3 style="margin:0">${t("Pricing & payment record")}</h3><div class="field-row">${field(t("Discount (Rs.)"),'discount',x.discount,'number','min="0" step="0.01" data-quote-field')}${field(t("Amount received (Rs.)"),'amount_paid',x.amount_paid,'number','min="0" step="0.01"')}</div><div class="field-row">${selectField(t("Payment status"),'payment_status',[['unpaid',t("Unpaid")],['partial',t("Partially paid")],['paid',t("Paid")],['refunded',t("Refunded")]],x.payment_status)}${selectField(t("Payment method"),'payment_method',[['cash',t("Cash")],['bank_transfer',t("Bank transfer")],['card',t("Card / POS")],['other',t("Other")]],x.payment_method)}</div>${textArea(t("Private staff notes"),'internal_notes',x.internal_notes)}<div class="form-actions"><button class="btn ghost" type="button" data-action="close-modal">${t("Cancel")}</button><button class="btn" type="submit">${b?t("Update reservation"):t("Save reservation")}</button></div></form>`);
}
function pair(label,value){return `<div class="detail-pair"><span>${h(labelFor(label))}</span><strong>${h(value??'—')}</strong></div>`}
function modalBookingView(b){const s=findSpace(b.space_id);return modalFrame(h(t('Reservation {reference}',{reference:b.reference})),`<div class="badge-row">${pill(b.status)} ${pill(b.payment_status)}</div><div style="margin-top:13px">${pair(t("Space"),spaceText(s))}${pair(t("Customer"),b.customer_name)}${pair(t("Email"),b.customer_email)}${pair(t("Phone"),b.customer_phone)}${pair(t("Start"),dateTime(b.start_at))}${pair(t("End"),dateTime(b.end_at))}${pair(t("Units / desks"),b.units_reserved)}${pair(t("Billing unit"),rateLabel(b.rate_type))}${pair(t("Total price"),money(b.amount))}${pair(t("Received"),money(b.amount_paid))}${pair(t("Balance"),money(Math.max(0,Number(b.amount||0)-Number(b.amount_paid||0))))}${pair(t("Payment method"),labelFor(b.payment_method))}${pair(t("Purpose"),b.purpose)}${pair(t("Attendees"),b.attendees)}${pair(t("Special requests"),b.special_requests)}${pair(t("Staff notes"),b.internal_notes)}${pair(t("Created"),dateTime(b.created_at))}</div><div class="form-actions">${btn(t("Delete record"),'delete-booking',b.id,'danger')} ${btn(t("Edit reservation"),'edit-booking',b.id,'soft')}<button class="btn" data-action="close-modal">${t("Done")}</button></div>`)}
function modalInquiryView(i){return modalFrame(t("Inquiry details"),`<div class="badge-row">${pill(i.status)}</div><div style="margin-top:16px">${pair(t("Name"),i.name)}${pair(t("Email"),i.email)}${pair(t("Phone"),i.phone)}${pair(t("Space"),spaceText(findSpace(i.space_id)))}${pair(t("Preferred start"),dateTime(i.start_at))}${pair(t("Preferred end"),dateTime(i.end_at))}${pair(t("Message"),i.message)}${pair(t("Received"),dateTime(i.created_at))}</div><div class="divider"></div><form data-form="inquiry-status" data-id="${h(i.id)}" class="form-grid">${selectField(t("Follow-up status"),'status',[['new',t("New")],['contacted',t("Contacted")],['converted',t("Converted")],['closed',t("Closed")]],i.status)}<div class="form-actions"><button class="btn ghost" type="button" data-action="close-modal">${t("Close")}</button><button class="btn soft" type="submit">${t("Save status")}</button><button class="btn" type="button" data-action="convert-inquiry" data-id="${h(i.id)}">${t("Create booking")}</button></div></form>`)}
function confirmDialog(title,body,action,id,label=t("Confirm")){return modalFrame(title,`<p>${body}</p><div class="form-actions"><button class="btn ghost" data-action="close-modal">${t("Keep record")}</button><button class="btn danger" data-action="${action}" data-id="${h(id)}">${label}</button></div>`,true)}
function render(){if(state.startupError){app.innerHTML=`<div class="auth-wrap"><div class="auth-card">${languageSelector()}<h2>${t("Workspace could not start")}</h2><p>${h(translateError(state.startupError))}</p><p>${t("Check")} <code>${"config.js"}</code> ${t("and your internet connection. For offline demo mode, leave the Supabase settings blank.")}</p><button class="btn" onclick="location.reload()">${t("Retry")}</button></div></div>`;return}if(!state.data){app.innerHTML=`<div class="loading-screen">${languageSelector()}<span class="loading-mark">${"T"}<span>.</span></span><p>${t("Loading workspace…")}</p></div>`;return}app.innerHTML=state.admin&&adminRoutes.includes(state.route)?adminShell():state.route==='login'?loginPage():state.route==='catalog'?catalogPublic():state.route==='request'?requestPublic():state.route==='availability'?publicCalendar():homePublic();if(state.modal)app.insertAdjacentHTML('beforeend',state.modal())}
function getPayload(form){return Object.fromEntries(new FormData(form).entries())}
function nums(row,keys){for(const k of keys)row[k]=Number(row[k]||0);return row}
function replaceWithQuote(form){
 let f=getPayload(form);const s=findSpace(f.space_id),out=form.querySelector('.quote-preview');if(!out)return;
 const rateSelect=form.elements.rate_type;
 if(s&&rateSelect&&rateForSpace(s,f.rate_type)===0){const preferred=['hour','day','week','month'].find(x=>rateForSpace(s,x)>0);if(preferred){rateSelect.value=preferred;f=getPayload(form)}}
 if(!s){out.textContent=t("Choose a space.");return}
 try{const b={...f,start_at:isoLocal(f.start_at),end_at:isoLocal(f.end_at)};const q=quoteBooking(s,b);const a=availabilityFor(s,state.data.bookings,state.data.blackouts,b.start_at,b.end_at,Number(f.units_reserved||1),form.dataset.id||null);
 out.innerHTML=`<strong>${t("Estimated total:")} ${money(q.total)}</strong> · ${q.periodUnits} ${t("billing period(s) ·")} ${Number(f.units_reserved||1)} ${t("unit(s)")}<br><span class="${a.ok?'success-text':'danger-text'}">${a.ok?t("✓ Available at the selected dates and times"):'✕ '+h(translateError(a.reason))}</span>`;
 }catch{out.textContent=t("Select a valid start/end time to see the quote.")}
}
function downloadCsv(table){const keys={bookings:['reference','customer_name','customer_email','customer_phone','space_id','start_at','end_at','units_reserved','rate_type','amount','amount_paid','payment_status','payment_method','status','purpose','attendees','special_requests','internal_notes'],spaces:['name','type','capacity','inventory_count','amenities','rate_hour','rate_day','rate_week','rate_month','conditions','is_active'],customers:['full_name','email','phone','company','notes'],inquiries:['name','email','phone','space_id','start_at','end_at','message','status','created_at']}[table];if(!keys)return;const url=URL.createObjectURL(new Blob(['\ufeff'+csv(state.data[table],keys)],{type:'text/csv;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download=`trace-expert-city-${table}-${new Date().toISOString().slice(0,10)}.csv`;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);showToast(t('{table} CSV exported.',{table:labelFor(table)}))}
async function clickAction(target){
 const act=target.dataset.action,id=target.dataset.id;
 if(act==='close-modal'||act==='modal-backdrop'){state.modal=null;render();return}
 if(act==='menu'){state.menu=!state.menu;render();return}
 if(act==='enter-demo'){await signIn();state.admin=true;await refresh();navigate('dashboard');return}
 if(act==='logout'){await signOut();state.admin=false;await refresh();navigate('home');return}
 if(act==='public-request'){state.activeInquirySpace=id;state.activeInquiryDay='';await navigate('request');return}if(act==='public-request-on-day'){state.activeInquirySpace=id;state.activeInquiryDay=state.publicDay;await navigate('request');return}
if(act==='public-prev-day'||act==='public-next-day'||act==='public-today'||act==='public-select-day'){
 state.publicDay=act==='public-today'?localDay():act==='public-select-day'?target.dataset.day:shiftDay(state.publicDay,act==='public-prev-day'?-1:1);
 await refreshPublicCalendar();return;
}
if(act==='refresh-public-calendar'){await refreshPublicCalendar();return}

 if(act==='filter-type'){state.type=target.dataset.value;render();return}
 if(act==='new-space'){state.modal=()=>modalSpace(null);render();return}
 if(act==='edit-space'){state.modal=()=>modalSpace(item('spaces',id));render();return}
 if(act==='new-booking'){state.modal=()=>modalBooking(null);render();return}
 if(act==='edit-booking'){state.modal=()=>modalBooking(item('bookings',id));render();return}
 if(act==='view-booking'){state.modal=()=>modalBookingView(item('bookings',id));render();return}
 if(act==='view-inquiry'){state.modal=()=>modalInquiryView(item('inquiries',id));render();return}
 if(act==='new-customer'){state.modal=()=>modalCustomer();render();return}
 if(act==='edit-customer'){state.modal=()=>modalCustomer(item('customers',id));render();return}
 if(act==='new-block'){state.modal=()=>modalBlock();render();return}
 if(act==='edit-block'){state.modal=()=>modalBlock(item('blackouts',id));render();return}
 if(act==='convert-inquiry'){state.modal=()=>modalBooking(null,item('inquiries',id));render();return}
 if(act==='calendar-slot'){const d=state.calendarDay,hr=Number(target.dataset.hour);state.modal=()=>modalBooking(null,null,{spaceId:id,start:dtLocal(d,hr),end:dtLocal(d,hr+1)});render();return}
 if(act==='export'){downloadCsv(id);return}
 if(act==='toggle-space'){
  const s=item('spaces',id);if(!s)return;
  const {id:old,created_at,...rest}=s;await save('spaces',{...rest,is_active:!s.is_active},old);await refresh();render();showToast(s.is_active?t("Space archived; booking history retained."):t("Space restored."));return;
 }
 if(act==='delete-space'){state.modal=()=>confirmDialog(t("Delete space permanently?"),t("Only spaces without associated reservations, inquiries or maintenance blocks can be permanently deleted. Otherwise archive the space to preserve history."),'confirm-delete-space',id,t("Delete space"));render();return}
 if(act==='delete-customer'){state.modal=()=>confirmDialog(t("Delete customer?"),t("This removes their contact profile. Customers linked to bookings must be retained for history."),'confirm-delete-customer',id,t("Delete customer"));render();return}
 if(act==='delete-block'){state.modal=()=>confirmDialog(t("Remove blocked period?"),t("Removing this block makes the space available for new reservations."),'confirm-delete-block',id,t("Remove block"));render();return}
 if(act==='delete-booking'){state.modal=()=>confirmDialog(t("Delete reservation permanently?"),t("This permanently removes the reservation history. Prefer cancellation for real customer bookings."),'confirm-delete-booking',id,t("Delete reservation"));render();return}
 if(act==='cancel-booking'){state.modal=()=>confirmDialog(t("Cancel this reservation?"),t("The reserved dates will be released for other customers. The booking history remains visible."),'confirm-cancel-booking',id,t("Cancel reservation"));render();return}
 if(act.startsWith('confirm-delete-')){
  const tab={'confirm-delete-space':'spaces','confirm-delete-customer':'customers','confirm-delete-block':'blackouts','confirm-delete-booking':'bookings'}[act];await remove(tab,id);await refresh();state.modal=null;render();showToast(t("Record deleted."));return
 }
 if(act==='confirm-cancel-booking'){
  const b=item('bookings',id),{id:old,created_at,...rest}=b;await save('bookings',{...rest,status:'cancelled'},old);await refresh();state.modal=null;render();showToast(t("Reservation cancelled. Dates are available again."));return;
 }
 if(act==='reset-demo'){state.modal=()=>confirmDialog(t("Reset demo workspace?"),t("Your edits, test inquiries and reservations in this browser will be replaced with the starter demo records."),'confirm-reset','demo',t("Reset everything"));render();return}
 if(act==='confirm-reset'){demoReset();await refresh();state.modal=null;render();showToast(t("Demo data restored."));return}
}
async function submitForm(form){const f=getPayload(form),which=form.dataset.form,id=form.dataset.id;
 if(which==='login'){await signIn(f.email,f.password);state.admin=true;await refresh();navigate('dashboard');showToast(t("Welcome to your workspace."));return}
 if(which==='inquiry'){
  if(f.company_website)return;
  if(!f.name.trim()||!f.email.trim()||!f.phone.trim())throw Error(t("Please provide a name, email and phone number."));
  const inquiry={name:f.name.trim(),email:f.email.trim(),phone:f.phone.trim(),space_id:f.space_id,start_at:isoLocal(f.start_at),end_at:isoLocal(f.end_at),message:f.message?.trim()||''};
  if(!(new Date(inquiry.end_at)>new Date(inquiry.start_at)))throw Error(t("Please select an end date/time after the start date/time."));
  await submitInquiry(inquiry);await refresh();navigate('catalog');showToast(isCloud()?t("Inquiry submitted. Our team can review it in the staff portal."):t("Demo inquiry saved on this browser. Email notifications are not enabled."));return;
 }
 if(which==='space'){
  const payload=nums({...f},['capacity','inventory_count','rate_hour','rate_day','rate_week','rate_month']);payload.is_active=form.elements.is_active.checked;
  await save('spaces',payload,id);await refresh();state.modal=null;render();showToast(id?t("Space updated."):t("Space added."));return;
 }
 if(which==='booking'){
  const values=nums({...f},['units_reserved','attendees','discount','amount_paid']);values.start_at=isoLocal(f.start_at);values.end_at=isoLocal(f.end_at);values.customer_id=values.customer_id||null;
  if(!values.customer_email && !values.customer_phone)throw Error(t("Add at least one customer contact method."));
  const s=findSpace(values.space_id);if(!s)throw Error(t("Choose a valid space."));
  const quote=quoteBooking(s,values);if(!quote.periodUnits)throw Error(t("Choose a valid booking date and time range."));
  if(rateForSpace(s,values.rate_type)<=0)throw Error(t("This space has no configured price for that billing unit. Choose another billing unit or edit the space rates."));
  values.amount=quote.total;values.reference=id?item('bookings',id).reference:`TEC-${Date.now().toString(36).toUpperCase().slice(-8)}`;
  if(values.amount_paid>values.amount)throw Error(t("Amount received cannot be greater than the total price."));
  // Link customer contact records automatically for new reservations; staff can still edit them separately.
  if(!values.customer_id){
    const match=state.data.customers.find(c=>(values.customer_email&&c.email?.toLowerCase()===values.customer_email.toLowerCase())||(!values.customer_email&&values.customer_phone&&c.phone===values.customer_phone));
    if(match)values.customer_id=match.id;
    else if(values.status!=='cancelled'){
      const a=availabilityFor(s,state.data.bookings,state.data.blackouts,values.start_at,values.end_at,values.units_reserved,id||null);
      if(!a.ok)throw Error(a.reason);
      const added=await save('customers',{full_name:values.customer_name,email:values.customer_email||'',phone:values.customer_phone||'',company:'',notes:''});
      values.customer_id=added.id;
    }
  }
  await save('bookings',values,id);const inquiryId=form.dataset.inquiry;
  if(inquiryId){try{await save('inquiries',{status:'converted'},inquiryId)}catch(e){showToast(t("Reservation saved but inquiry status could not be updated."),true)}}
  await refresh();state.modal=null;render();showToast(id?t("Reservation updated and checked for clashes."):t("Reservation created; no time clash detected."));return;
 }
 if(which==='blackout'){
  const values={...f,start_at:isoLocal(f.start_at),end_at:isoLocal(f.end_at)};await save('blackouts',values,id);await refresh();state.modal=null;render();showToast(t("Blocked period saved."));return;
 }
 if(which==='customer'){
  if(!f.full_name?.trim())throw Error(t("Enter the customer name."));
  await save('customers',f,id);await refresh();state.modal=null;render();showToast(t("Customer saved."));return;
 }
 if(which==='inquiry-status'){
  await save('inquiries',{status:f.status},id);await refresh();state.modal=null;render();showToast(t("Inquiry updated."));return;
 }
 if(which==='settings'){
  await save('org_settings',{...f,currency:'LKR'},1);await refresh();render();showToast(t("Company information saved."));return;
 }
}
// Event delegation makes dynamically rendered screens and dialogs fully interactive.
document.addEventListener('click',async e=>{
 const link=e.target.closest('[data-go]');if(link){e.preventDefault();navigate(link.dataset.go);return}
 const target=e.target.closest('[data-action]');if(!target)return;
 if(target.dataset.action==='modal-backdrop'&&e.target!==target)return;
 e.preventDefault();
 if(target.hasAttribute('disabled'))return;
 target.disabled=true;
 try{await clickAction(target)}catch(err){showToast(err?.message||t("Something went wrong."),true);console.error(err)}finally{if(target.isConnected)target.disabled=false}
});
document.addEventListener('submit',async e=>{
 const form=e.target.closest('form[data-form]');if(!form)return;e.preventDefault();
 const submit=form.querySelector('button[type="submit"]');if(submit)submit.disabled=true;
 try{await submitForm(form)}catch(err){showToast(err?.message||t("Unable to save."),true);console.error(err)}finally{if(submit?.isConnected)submit.disabled=false}
});
document.addEventListener('change',e=>{
 const el=e.target;
 if(typeof el.setCustomValidity==='function')el.setCustomValidity('');
 if(el.matches('[data-language]')){changeLanguage(el.value);return}
 if(el.matches('[data-filter="type"],[data-filter="status"],[data-filter="calendar-day"]')){
   if(el.dataset.filter==='type')state.type=el.value;
   if(el.dataset.filter==='status')state.status=el.value;
   if(el.dataset.filter==='calendar-day')state.calendarDay=el.value;
   render();return;
 }
 if(el.matches('[data-filter="public-day"]')){state.publicDay=el.value;refreshPublicCalendar();return}
 if(el.matches('[data-filter="public-space"]')){state.publicSpaceId=el.value;render();return}
 if(el.matches('[data-customer-change]')){
   const c=item('customers',el.value);const form=el.closest('form');if(c&&form){form.elements.customer_name.value=c.full_name;form.elements.customer_email.value=c.email||'';form.elements.customer_phone.value=c.phone||'';}
 }
 if(el.matches('[data-quote-field]'))replaceWithQuote(el.closest('form'));
});
document.addEventListener('invalid',e=>localizeValidation(e.target),true);
document.addEventListener('input',e=>{
 const el=e.target;
 if(typeof el.setCustomValidity==='function')el.setCustomValidity('');
 if(el.dataset.filter==='search'){
   state.search=el.value;const position=el.selectionStart;render();const same=document.querySelector('input[data-filter="search"]');if(same){same.focus();same.setSelectionRange(position,position)}
 }
 if(el.matches('[data-quote-field]'))replaceWithQuote(el.closest('form'));
});
document.addEventListener('keydown',e=>{if(e.key==="Escape"&&state.modal){state.modal=null;render()}});
render();
(async()=>{
 try{
   const result=await init();state.admin=result.admin;await refresh();let route=location.hash.replace('#','')||'home';if(!['home','catalog','request','availability','login',...adminRoutes].includes(route))route='home';if(adminRoutes.includes(route)&&!state.admin)route='login';state.route=route;render();if(route==='availability')await refreshPublicCalendar();
 }catch(err){console.error(err);state.startupError=err.message;render();}
})();
